	  startEscape() {
	    const action = this.runtime.handleEscape(this.keyboard);
	    if (action === "ignored" || action === "input") {
	      this.updateResultText();
	      return;
	    }
	    if (action === "suspended") {
	      this.keyboard.setOptions({
	        fnOnKeyDown: this.fnWaitForContinueHandler
	      });
	    } else {
	      this.removeKeyBoardHandler();
	    }
	    this.startMainLoop();
	  }
